<tr><td><a href="/products/acer-predator-helios-neo-16s-ai-phn16s7191aw-2025-intel-core-ultra-9-275hx-rtx-5060">Acer Predator Helios Neo 16S AI PHN16S‑71‑91AW 2025 (Intel Core Ultra 9 275HX)</a></td><td>16GB/1TB</td><td>Rs 3,01,999</td></tr>
